void initDisplay(bool SD_enable) {
  digitalWrite(15, HIGH);

  tft.begin();
  tft.setRotation(1);
  tft.fillScreen(TFT_BLACK);

  if (!SD_enable) {
#if SC2_DEBUG
    Serial.println("Display initialized without SD card.");
#endif
    return;
  }

  if (!SD.begin(5, tft.getSPIinstance())) {
#if SC2_DEBUG
    Serial.println("Card Mount Failed");
#endif
    return;
  }

  uint8_t cardType = SD.cardType();
  if (cardType == CARD_NONE) {
#if SC2_DEBUG
    Serial.println("No SD card attached");
#endif
    return;
  }

#if SC2_DEBUG
  Serial.print("SD Card Type: ");
  if (cardType == CARD_MMC) {
    Serial.println("MMC");
  } else if (cardType == CARD_SD) {
    Serial.println("SDSC");
  } else if (cardType == CARD_SDHC) {
    Serial.println("SDHC");
  } else {
    Serial.println("UNKNOWN");
  }
#endif
}

static void ensureStaticLayout() {
  static bool drawn = false;
  if (drawn) {
    return;
  }

  tft.fillScreen(TFT_BLACK);
  tft.setTextColor(TFT_WHITE);
  tft.setTextSize(2);
  tft.drawString("Accel:", 10, 10);
  tft.drawString("Regen:", 10, 30);

  // BMS telemetry labels (values drawn dynamically to the right)
  const int bmsY0 = 250;
  tft.drawString("SOC", 10, bmsY0);
  tft.drawString("Pack", 200, bmsY0);
  tft.drawString("HiC", 10, bmsY0 + 18);
  tft.drawString("LoC", 200, bmsY0 + 18);
  tft.drawString("HiT", 10, bmsY0 + 36);
  tft.drawString("LoT", 200, bmsY0 + 36);
  tft.drawString("I", 10, bmsY0 + 54);
  drawn = true;
}

static bool updateRightField(int y, const char *value, char *lastValue, size_t lastSize,
                             int clearWidth) {
  if (strncmp(value, lastValue, lastSize) == 0) {
    return false;
  }

  tft.setTextSize(2);
  int textWidth = tft.textWidth(value);
  int x = WIDTH - textWidth - 8;
  tft.fillRect(WIDTH - clearWidth, y, clearWidth, 16, TFT_BLACK);
  tft.setTextColor(TFT_WHITE);
  tft.drawString(value, x, y);
  strncpy(lastValue, value, lastSize - 1);
  lastValue[lastSize - 1] = '\0';
  return true;
}

static bool updatePercentField(int x, int y, const char *value, char *lastValue,
                               size_t lastSize, int clearWidth) {
  if (strncmp(value, lastValue, lastSize) == 0) {
    return false;
  }

  tft.fillRect(x, y, clearWidth, 16, TFT_BLACK);
  tft.setTextColor(TFT_WHITE);
  tft.setTextSize(2);
  tft.drawString(value, x, y);
  strncpy(lastValue, value, lastSize - 1);
  lastValue[lastSize - 1] = '\0';
  return true;
}

static bool updateCenteredText(int y, int textSize, uint16_t color, const char *text,
                               char *lastText, size_t lastSize, int clearWidth) {
  if (strncmp(text, lastText, lastSize) == 0) {
    return false;
  }

  int clearX = (WIDTH - clearWidth) / 2;
  int textHeight = textSize * 8;
  tft.fillRect(clearX, y, clearWidth, textHeight, TFT_BLACK);
  tft.setTextColor(color);
  tft.setTextSize(textSize);
  tft.drawString(text, (WIDTH - tft.textWidth(text)) / 2, y);
  strncpy(lastText, text, lastSize - 1);
  lastText[lastSize - 1] = '\0';
  return true;
}

static bool updateRightAlignedText(int centerX, int offsetX, int y, int textSize,
                                   uint16_t color, const char *text, char *lastText,
                                   size_t lastSize, int clearWidth) {
  if (strncmp(text, lastText, lastSize) == 0) {
    return false;
  }

  tft.setTextSize(textSize);
  int textX = (centerX + offsetX) - (tft.textWidth(text) / 2);
  tft.fillRect(textX - 2, y, clearWidth, textSize * 8, TFT_BLACK);
  tft.setTextColor(color);
  tft.drawString(text, textX, y);
  strncpy(lastText, text, lastSize - 1);
  lastText[lastSize - 1] = '\0';
  return true;
}

static bool updateLeftAlignedText(int centerX, int offsetX, int y, int textSize,
                                  uint16_t color, const char *text, char *lastText,
                                  size_t lastSize, int clearWidth) {
  if (strncmp(text, lastText, lastSize) == 0) {
    return false;
  }

  tft.setTextSize(textSize);
  int textX = (centerX - offsetX) - (tft.textWidth(text) / 2);
  tft.fillRect(textX - 2, y, clearWidth, textSize * 8, TFT_BLACK);
  tft.setTextColor(color);
  tft.drawString(text, textX, y);
  strncpy(lastText, text, lastSize - 1);
  lastText[lastSize - 1] = '\0';
  return true;
}

static bool updateBitmapIfChanged(bool changed, int x, int y, const uint8_t *bitmap,
                                  int w, int h, uint16_t color) {
  if (!changed) {
    return false;
  }

  tft.drawBitmap(x, y, bitmap, w, h, color);
  return true;
}

void renderMinimalDisplay(float speed) {
  static bool hasPreviousFrame = false;
  static char lastAccelBuffer[8] = "";
  static char lastRegenBuffer[8] = "";
  static char lastSpeedBuffer[12] = "";
  static char lastOdoBuffer[12] = "";
  static char lastLapBuffer[12] = "";
  static char lastDirectionBuffer[4] = "";
  static char lastDriveModeText[4] = "";
  static char lastSocBuffer[12] = "";
  static char lastPackVBuffer[14] = "";
  static char lastHiCellBuffer[14] = "";
  static char lastLoCellBuffer[14] = "";
  static char lastHiTempBuffer[12] = "";
  static char lastLoTempBuffer[12] = "";
  static char lastCurrentBuffer[12] = "";
  static bool lastHeadlight = false;
  static bool lastLeftBlinkLit = false;
  static bool lastRightBlinkLit = false;
  static bool lastHazardLit = false;
  static bool lastBatteryFault = false;
  static int lastSpeedValue = -1;

  ensureStaticLayout();

  int speedValue = (int)lroundf(speed);
  if (speedValue < 0) {
    speedValue = 0;
  }

  portENTER_CRITICAL(&stateMux);
  float local_throttle = throttle;
  uint8_t local_regen_brake_percent = regen_brake_percent;
  Digital_Data local_digital_data = const_cast<Digital_Data&>(digital_data);
  bool local_hazards = hazards;
  uint8_t local_drive_mode = drive_mode;
  bool local_battery_fault_active = battery_fault_active;
  uint16_t local_lap_count = lap_count;
  float local_battery_soc = battery_soc;
  float local_low_temp_c = battery_low_temp_c;
  float local_high_temp_c = battery_high_temp_c;
  float local_high_cell_v = battery_high_cell_v;
  float local_low_cell_v = battery_low_cell_v;
  float local_pack_abs_current_a = battery_pack_abs_current_a;
  float local_est_pack_v = battery_est_pack_v;
  portEXIT_CRITICAL(&stateMux);

  int accelPercent = (int)lroundf((local_throttle / (float)THROTTLE_SENT_MAX) * 100.0f);
  if (accelPercent < 0) accelPercent = 0;
  if (accelPercent > 100) accelPercent = 100;

  int regenPercent = local_regen_brake_percent;
  if (regenPercent < 0) regenPercent = 0;
  if (regenPercent > 100) regenPercent = 100;

  int socPercent = (int)lroundf(local_battery_soc);
  if (socPercent < 0) socPercent = 0;
  if (socPercent > 100) socPercent = 100;

  bool headlight = local_digital_data.headlight;
  bool leftBlink = local_digital_data.left_blink;
  bool rightBlink = local_digital_data.right_blink;
  bool hazardState = local_hazards;
  uint8_t currentDriveMode = local_drive_mode;
  bool directionSwitch = local_digital_data.direction_switch;
  bool batteryFault = local_battery_fault_active;
  bool blinkPhase = getBlinkPhase();

  bool leftBlinkLit = (leftBlink || hazardState) && blinkPhase;
  bool rightBlinkLit = (rightBlink || hazardState) && blinkPhase;
  bool hazardLit = hazardState && blinkPhase;

  char accelBuffer[8];
  char regenBuffer[8];
  char speedBuffer[12];
  char odoBuffer[12];
  char lapBuffer[12];
  char directionBuffer[4];
  char socBuffer[12];
  char packVBuffer[14];
  char hiCellBuffer[14];
  char loCellBuffer[14];
  char hiTempBuffer[12];
  char loTempBuffer[12];
  char currentBuffer[12];

  snprintf(accelBuffer, sizeof(accelBuffer), "%02d%%", accelPercent);
  snprintf(regenBuffer, sizeof(regenBuffer), "%02d%%", regenPercent);
  dtostrf(speed, 0, 1, speedBuffer);
  snprintf(odoBuffer, sizeof(odoBuffer), "%lu mi", (unsigned long)getOdometerMiles());
  snprintf(lapBuffer, sizeof(lapBuffer), "Lap %u", (unsigned)local_lap_count);
  snprintf(directionBuffer, sizeof(directionBuffer), "%s", directionSwitch ? "Fwd" : "Rev");
  snprintf(socBuffer, sizeof(socBuffer), "%d%%", socPercent);
  snprintf(packVBuffer, sizeof(packVBuffer), "%.1fV", local_est_pack_v);
  snprintf(hiCellBuffer, sizeof(hiCellBuffer), "%.3fV", local_high_cell_v);
  snprintf(loCellBuffer, sizeof(loCellBuffer), "%.3fV", local_low_cell_v);
  snprintf(hiTempBuffer, sizeof(hiTempBuffer), "%.0fC", local_high_temp_c);
  snprintf(loTempBuffer, sizeof(loTempBuffer), "%.0fC", local_low_temp_c);
  snprintf(currentBuffer, sizeof(currentBuffer), "%.1fA", local_pack_abs_current_a);

  const char *driveModeText = currentDriveMode ? "Pwr" : "Eco";

  const int centerX = WIDTH / 2;
  const int topRowY = 55;
  const int iconRowY = 125;
  const int bmsY0 = 250;

  bool updated = false;
  updated |= updatePercentField(90, 10, accelBuffer, lastAccelBuffer, sizeof(lastAccelBuffer), 56);
  updated |= updatePercentField(90, 30, regenBuffer, lastRegenBuffer, sizeof(lastRegenBuffer), 56);
  updated |= updateRightField(10, odoBuffer, lastOdoBuffer, sizeof(lastOdoBuffer), 120);
  updated |= updateRightField(30, lapBuffer, lastLapBuffer, sizeof(lastLapBuffer), 120);

  updated |= updatePercentField(60, bmsY0, socBuffer, lastSocBuffer, sizeof(lastSocBuffer), 72);
  updated |= updatePercentField(260, bmsY0, packVBuffer, lastPackVBuffer, sizeof(lastPackVBuffer), 100);
  updated |= updatePercentField(60, bmsY0 + 18, hiCellBuffer, lastHiCellBuffer, sizeof(lastHiCellBuffer), 100);
  updated |= updatePercentField(260, bmsY0 + 18, loCellBuffer, lastLoCellBuffer, sizeof(lastLoCellBuffer), 100);
  updated |= updatePercentField(60, bmsY0 + 36, hiTempBuffer, lastHiTempBuffer, sizeof(lastHiTempBuffer), 72);
  updated |= updatePercentField(260, bmsY0 + 36, loTempBuffer, lastLoTempBuffer, sizeof(lastLoTempBuffer), 72);
  updated |= updatePercentField(40, bmsY0 + 54, currentBuffer, lastCurrentBuffer, sizeof(lastCurrentBuffer), 100);

  if (!hasPreviousFrame || speedValue != lastSpeedValue ||
      strncmp(speedBuffer, lastSpeedBuffer, sizeof(lastSpeedBuffer)) != 0) {
    tft.fillRect(centerX - 110, 135, 220, 48, TFT_BLACK);
    tft.setTextColor(TFT_WHITE);
    tft.setTextSize(6);
    tft.drawString(speedBuffer, (WIDTH - tft.textWidth(speedBuffer)) / 2, 135);
    strncpy(lastSpeedBuffer, speedBuffer, sizeof(lastSpeedBuffer) - 1);
    lastSpeedBuffer[sizeof(lastSpeedBuffer) - 1] = '\0';
    lastSpeedValue = speedValue;
    updated = true;
  }

  if (!hasPreviousFrame) {
    tft.setTextColor(TFT_WHITE);
    tft.setTextSize(2);
    tft.drawString("MPH", (WIDTH - tft.textWidth("MPH")) / 2, 193);
  }

  updated |= updateRightAlignedText(centerX, 110, 220, 3, 0x61D6, driveModeText,
                                    lastDriveModeText, sizeof(lastDriveModeText), 72);
  updated |= updateLeftAlignedText(centerX, 110, 220, 3, 0x24BE, directionBuffer,
                                     lastDirectionBuffer, sizeof(lastDirectionBuffer), 72);

  updated |= updateBitmapIfChanged(!hasPreviousFrame || batteryFault != lastBatteryFault,
                                   288, topRowY, image_bms_fault_bits, 96, 64,
                                   batteryFault ? 0xF206 : TFT_DARKGREY);
  updated |= updateBitmapIfChanged(!hasPreviousFrame || headlight != lastHeadlight, 192,
                                   topRowY, image_headlights_bits, 64, 52,
                                   headlight ? 0x4D6A : TFT_DARKGREY);
  updated |= updateBitmapIfChanged(!hasPreviousFrame || hazardLit != lastHazardLit, 96,
                                   topRowY, image_hazards_bits, 64, 64,
                                   hazardLit ? 0xFAA4 : TFT_DARKGREY);
  updated |= updateBitmapIfChanged(!hasPreviousFrame || rightBlinkLit != lastRightBlinkLit,
                                   358, iconRowY, image_right_blink_bits, 84, 60,
                                   rightBlinkLit ? 0xFF47 : TFT_DARKGREY);
  updated |= updateBitmapIfChanged(!hasPreviousFrame || leftBlinkLit != lastLeftBlinkLit, 38,
                                   iconRowY, image_left_blink_bits, 84, 60,
                                   leftBlinkLit ? 0xFF47 : TFT_DARKGREY);

  if (!updated && hasPreviousFrame) {
    return;
  }

  hasPreviousFrame = true;
  lastHeadlight = headlight;
  lastLeftBlinkLit = leftBlinkLit;
  lastRightBlinkLit = rightBlinkLit;
  lastHazardLit = hazardLit;
  lastBatteryFault = batteryFault;
}